  const digest = hash(`raid-relic-rune-v1:${normalized}`);
  const points = Array.from({ length: 8 }, (_, i) => `${16 + parseInt(digest.slice(i * 2, i * 2 + 2), 16) % 5 * 16},${16 + parseInt(digest.slice(16 + i * 2, 18 + i * 2), 16) % 5 * 16}`);
